<include file="Public:header"/>	<div class="mainbox">        <div style="margin-left: 10px;color: #9a9999">        </div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>小区名称</th>							<th>设备编号</th>							<th>设备名称</th>                            <th>视频格式</th>                            <th class="textcenter">操作</th>						</tr>					</thead>					<tbody>						<if condition="is_array($camera_device_list) AND !empty($camera_device_list)">							<volist name="camera_device_list" id="vo">								<tr>									<td>{pigcms{$vo.village_name}</td>									<td>{pigcms{$vo.camera_sn}</td>									<td>{pigcms{$vo.camera_name}</td>                                    <td>{pigcms{$vo.lookUrlType}</td>									<td class="textcenter">                                        <a href="javascript:void(0);" onclick="selectitem('{pigcms{$vo.camera_sn}','{pigcms{$vo.look_url}','{pigcms{$vo.lookUrlType}','{pigcms{$vo.camera_name}')">请选择</a>                                    </td>                                    								</tr>							</volist>                            <tr><td class="textcenter pagebar" colspan="5">{pigcms{$pagebar}</td></tr>						<else/>							<tr>                                <td class="textcenter red" colspan="5">列表为空，暂无数据！</td>                            </tr>						</if>					</tbody>				</table>			</div>		</form>	</div><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }</style><script>   function selectitem(camera_sn,look_url,lookUrlType,camera_name){               if (!camera_sn){            layer.alert('请选择一条监控视频数据');        }        var index = layer.load(1, {shade: [0.1,'#000'],time:3000});        parent.window.callbackFunc("{pigcms{$idstr}",camera_sn,look_url,lookUrlType,camera_name);        var index = parent.layer.getFrameIndex(window.name); //先得到当前iframe层的索引        parent.layer.close(index); //再执行关闭    };</script><include file="Public:footer"/>